CREATE OR REPLACE FUNCTION calculate_market_risk(
    flow bigint,
    rates numeric,
    scores numeric,
    counts integer,
    lifespan integer
) RETURNS numeric AS $$
BEGIN
    RETURN flow / 1000.0 + (rates * 0.2) + (scores * 0.3) + (counts * 0.1) - (lifespan / 100.0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    flow bigint,
    rates numeric,
    scores numeric,
    counts integer,
    lifespan integer
) RETURNS numeric AS $$
BEGIN
    RETURN (flow::numeric / 1000.0) + (rates * 0.2) + (scores * 0.3) + (counts::numeric * 0.1) - (lifespan::numeric / 100.0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
