END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    flow numeric,
    rates numeric,
    scores numeric,
    counts numeric,
    lifespan numeric
) RETURNS numeric AS $$
    SELECT flow / 1000 + (rates * 0.2) + (scores * 0.3) + (counts * 0.1) - lifespan / 100;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    mktreg character varying
) RETURNS numeric AS $$
DECLARE
    result numeric;
BEGIN
    SELECT (dlyflow::numeric / 1000) + (esccomprate * 0.2) + (interscore * 0.3) + (vendcount::numeric * 0.1) - (mktspan::numeric / 100)
    INTO result
    FROM markets
    WHERE mktregistry = mktreg;
    RETURN result;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    dlyflow numeric,
    esccomprate numeric,
    interscore numeric,
    vendcount numeric,
    mktspan numeric
) RETURNS numeric AS $$
BEGIN
    RETURN (dlyflow / 1000.0) + (esccomprate * 0.2) + (interscore * 0.3) + (vendcount * 0.1) - (mktspan / 100.0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    flow numeric,
    rates numeric,
    scores numeric,
    counts numeric,
    lifespan numeric
) RETURNS numeric AS $$
BEGIN
    RETURN ROUND(CAST((flow / 1000.0) + (rates * 0.2) + (scores * 0.3) + (counts * 0.1) - (lifespan / 100.0) AS numeric), 2);
END;
$$ LANGUAGE plpgsql;
